import pyomo.environ as pyo

DATA = {
    "store_types": ["retail", "factory"],
    "customers_per_store": {"retail": 200, "factory": 80},
    "employees_per_store": {"retail": 6, "factory": 4},
    "min_customers": 1200,
    "max_employees": 50,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Set of store types
    model.STORE_TYPES = pyo.Set(initialize=d["store_types"])

    # Decision variable: number of stores of each type to open
    model.stores = pyo.Var(
        model.STORE_TYPES,
        within=pyo.NonNegativeIntegers,
    )

    # Objective: minimize total number of stores opened
    def obj_rule(m):
        return sum(m.stores[t] for t in m.STORE_TYPES)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: at least min_customers customers served per day
    def customers_rule(m):
        return sum(
            d["customers_per_store"][t] * m.stores[t] for t in m.STORE_TYPES
        ) >= d["min_customers"]

    model.customer_requirement = pyo.Constraint(rule=customers_rule)

    # Constraint: at most max_employees employees used
    def employees_rule(m):
        return sum(
            d["employees_per_store"][t] * m.stores[t] for t in m.STORE_TYPES
        ) <= d["max_employees"]

    model.employee_limit = pyo.Constraint(rule=employees_rule)

    return model


